SELECT s.name, s.releaseDate FROM sets s
WHERE s.type = 'from_the_vault' AND s.code NOT IN (SELECT DISTINCT setCode FROM set_translations)
ORDER BY s.releaseDate;

SELECT ROUND(
  (SELECT SUM(Consumption) FROM yearmonth WHERE Date = (
    SELECT Date FROM yearmonth WHERE Date LIKE '2013%' GROUP BY Date ORDER BY SUM(Consumption) DESC LIMIT 1
  ))
  -
  (SELECT SUM(Consumption) FROM yearmonth WHERE Date = (
    SELECT Date FROM yearmonth WHERE Date LIKE '2012%' GROUP BY Date ORDER BY SUM(Consumption) DESC LIMIT 1
  ))
) AS ConsumptionDifference;
